import { supabase } from './supabase.js';
import { coachingSectionLabel, coachingQuestionLabel, formatCoachingAnswer } from './coaching-questionnaire.js';

const $=selector=>document.querySelector(selector),esc=(value='')=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const fmt=value=>value?new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value)):'—';
const fmtTime=value=>value?new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value)):'—';
let user,clients=[],selected,detail={},modules=[],channel,isAdmin=false,selectionRequest=0;
let availabilitySlots=[],availabilityMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1),availabilityDay=new Date();
const notify=(message,tone='')=>{const node=$('#coach-alert');node.hidden=!message;node.textContent=message;node.dataset.tone=tone;};

function renderMetrics(){const active=clients.filter(row=>row.status==='active').length,onboarding=clients.filter(row=>!row.questionnaire_submitted).length,unread=clients.reduce((sum,row)=>sum+Number(row.unread_messages||0),0);$('#coach-metrics').innerHTML=[['CLIENTS ACTIFS',active,'Suivis en cours'],['ADMISSIONS',onboarding,'Questionnaires à relire'],['BILANS',clients.filter(row=>row.checkin_due).length,'Suivis attendus'],['MESSAGES',unread,'En attente de réponse'],['PLANS ACTIFS',clients.filter(row=>row.has_active_plan).length,'Parcours publiés'],['COMPTES RENDUS',clients.filter(row=>row.review_due).length,'À préparer']].map(([label,value,copy])=>`<article><small>${label}</small><strong>${value}</strong><span>${copy}</span></article>`).join('');}
function renderClients(){const q=$('#coach-client-search').value.trim().toLowerCase(),filter=$('#coach-client-filter').value,rows=clients.filter(row=>`${row.display_name} ${row.email}`.toLowerCase().includes(q)).filter(row=>filter==='all'||filter==='questionnaire'&&row.questionnaire_submitted||filter==='plan'&&row.has_active_plan||filter==='checkin'&&row.checkin_due||filter==='review'&&row.review_due||row.status===filter);$('#coach-client-list').innerHTML=rows.length?rows.map(row=>`<button type="button" data-client="${row.client_id}" class="${selected?.client_id===row.client_id?'active':''}"><span class="coach-client-avatar" ${row.avatar_url?`style="background-image:url('${row.avatar_url.replaceAll("'",'%27')}')"`:''}>${row.avatar_url?'':esc(row.display_name[0]||'S')}</span><span><strong>${esc(row.display_name)}</strong><small>${row.status==='onboarding'?'Admission en cours':row.status==='active'?'Coaching actif':esc(statusLabel(row.status))}</small></span>${Number(row.unread_messages)?`<b>${row.unread_messages}</b>`:''}</button>`).join(''):'<p class="coaching-empty">Aucun client.</p>';}
const statusLabel=status=>({onboarding:'Admission',active:'Actif',completed:'Terminé',paused:'En pause',cancelled:'Accès retiré',todo:'À faire',in_progress:'En cours',assigned:'Assignée',started:'Commencée',submitted:'Transmis',reviewed:'Relu'}[status]||(status?'État inconnu':''));
function miniList(rows,kind){return rows.length?rows.map(row=>`<article><div><strong>${esc(row.title||row.week_summary||row.content||'Point de suivi')}</strong><p>${esc(row.description||row.note||row.main_difficulty||row.content||'')}</p><small>${statusLabel(row.status)}${row.due_at||row.target_date?` · ${fmt(row.due_at||row.target_date)}`:''}</small></div>${kind&&row.status!=='completed'?`<button type="button" data-coach-complete="${row.id}" data-kind="${kind}" aria-label="Terminer">✓</button>`:''}</article>`).join(''):'<p class="coaching-empty">Aucun élément.</p>';}
function renderDossier(){
  const profile=detail.profile||{},summary=profile.summary||{},responses=detail.responses||[],scores=detail.checkins?.[0];
  $('#coach-dossier').innerHTML=`<header class="coach-dossier-head"><div class="coach-identity"><span class="coach-client-avatar large" ${selected.avatar_url?`style="background-image:url('${selected.avatar_url.replaceAll("'",'%27')}')"`:''}>${selected.avatar_url?'':esc(selected.display_name[0])}</span><div><span class="eyebrow">DOSSIER CLIENT</span><h2>${esc(selected.display_name)}</h2><p>${esc(selected.email||'')} · ${statusLabel(selected.status)}</p></div></div><div class="coach-actions"><details class="coach-action-menu"><summary>Ajouter au parcours <span>＋</span></summary><div><button data-new="goal">Objectif</button><button data-new="task">Action</button><button data-new="habit">Habitude</button><button data-new="assignment">Leçon</button><button data-new="checkin">Bilan</button><button data-new="appointment">Rendez-vous</button><button data-new="plan">Plan</button><button data-new="review">Compte rendu</button><button data-new="note">Note privée</button></div></details>${isAdmin&&selected.status!=='cancelled'?'<button type="button" class="danger" data-remove-coaching title="Retirer l’accès Coaching">Retirer le Coaching</button>':''}</div></header>
  <nav class="coach-dossier-nav"><button class="active" data-dossier-tab="overview">Synthèse</button><button data-dossier-tab="admission">Admission</button><button data-dossier-tab="actions">Actions</button><button data-dossier-tab="checkins">Suivis</button><button data-dossier-tab="messages">Messages</button><button data-dossier-tab="notes">Notes privées</button></nav>
  <div class="coach-dossier-tab active" data-tab="overview"><div class="coach-summary-grid"><article><small>OBJECTIF PRINCIPAL</small><h3>${esc(summary.main_goal||'À définir')}</h3><p>${esc(summary.time_horizon||'')}</p></article><article><small>PRIORITÉS</small><p>${(profile.priorities||[]).map(item=>`<span class="coach-tag">${esc(item)}</span>`).join('')||'À préciser'}</p><button type="button" data-new="profile">Modifier</button></article><article><small>CONTRAINTES</small><p>${(profile.constraints||[]).map(item=>`<span class="coach-tag muted">${esc(item)}</span>`).join('')||'Aucune renseignée'}</p></article><article><small>DERNIER BILAN</small><h3>${scores?`${scores.energy||'—'}/10 énergie`:'Aucun bilan'}</h3><p>${scores?esc(scores.main_win||scores.week_summary||''):''}</p></article></div><section class="coach-block"><header><h3>Plan actif</h3></header>${miniList(detail.plans||[])}</section><section class="coach-block"><header><h3>Prochain rendez-vous</h3></header>${miniList((detail.appointments||[]).map(row=>({...row,title:fmtTime(row.starts_at),description:row.note})))}</section></div>
  <div class="coach-dossier-tab" data-tab="admission"><section class="coach-block"><header><h3>Réponses d’admission</h3><small>${responses.length} réponses</small></header><div class="coach-response-grid">${responses.map(row=>`<article><small>${esc(coachingSectionLabel(row.section_key))}</small><strong>${esc(coachingQuestionLabel(row.question_key))}</strong><p>${esc(formatCoachingAnswer(row.question_key,row.answer))}</p></article>`).join('')||'<p class="coaching-empty">Questionnaire non transmis.</p>'}</div></section></div>
  <div class="coach-dossier-tab" data-tab="actions"><div class="coach-two-columns"><section class="coach-block"><header><h3>Objectifs</h3></header>${miniList(detail.goals||[],'goals')}</section><section class="coach-block"><header><h3>Actions</h3></header>${miniList(detail.tasks||[],'tasks')}</section><section class="coach-block"><header><h3>Habitudes</h3></header>${miniList(detail.habits||[])}</section><section class="coach-block"><header><h3>Leçons assignées</h3></header>${miniList((detail.assignments||[]).map(row=>({...row,title:row.modules?.title||'Leçon'})))}</section></div></div>
  <div class="coach-dossier-tab" data-tab="checkins"><section class="coach-block">${(detail.checkins||[]).map(row=>`<article class="coach-checkin"><header><strong>Semaine du ${fmt(row.period_start)}</strong><span>${statusLabel(row.status)}</span></header><div><b>Énergie ${row.energy||'—'}/10</b><b>Sommeil ${row.sleep||'—'}/10</b><b>Alimentation ${row.nutrition||'—'}/10</b><b>Mouvement ${row.activity||'—'}/10</b></div><h4>Victoire</h4><p>${esc(row.main_win)}</p><h4>Difficulté</h4><p>${esc(row.main_difficulty)}</p><h4>Besoin exprimé</h4><p>${esc(row.help_needed)}</p></article>`).join('')||'<p class="coaching-empty">Aucun bilan.</p>'}</section></div>
  <div class="coach-dossier-tab" data-tab="messages"><section class="coach-block coach-thread"><div id="coach-message-list">${messageMarkup()}</div><form id="coach-message-form"><textarea name="content" rows="2" maxlength="4000" placeholder="Répondre au client…" required></textarea><button type="submit">→</button></form></section></div>
  <div class="coach-dossier-tab" data-tab="notes"><section class="coach-block"><p class="coach-confidential">Ces notes restent strictement invisibles au client.</p>${miniList(detail.notes||[])}</section></div>`;
}
function messageMarkup(){return (detail.messages||[]).map(row=>`<article class="${row.sender_id===user.id?'mine':'client'}"><small>${row.sender_id===user.id?'Vous':esc(selected.display_name)} · ${fmtTime(row.created_at)}</small><p>${esc(row.content)}</p></article>`).join('')||'<p class="coaching-empty">Aucun message privé.</p>';}
async function selectClient(id){const requestId=++selectionRequest;selected=clients.find(row=>row.client_id===id);renderClients($('#coach-client-search').value);if(channel)await supabase.removeChannel(channel);const requests={profile:supabase.from('coaching_profiles').select('*').eq('client_id',id).maybeSingle(),responses:supabase.from('coaching_questionnaire_responses').select('*').eq('client_id',id).order('answered_at'),goals:supabase.from('coaching_goals').select('*').eq('client_id',id).order('created_at',{ascending:false}),tasks:supabase.from('coaching_tasks').select('*').eq('client_id',id).order('created_at',{ascending:false}),habits:supabase.from('coaching_habits').select('*').eq('client_id',id).order('created_at',{ascending:false}),assignments:supabase.from('coaching_assignments').select('*,modules(title)').eq('client_id',id).order('created_at',{ascending:false}),checkins:supabase.from('coaching_checkins').select('*').eq('client_id',id).order('period_start',{ascending:false}),plans:supabase.from('coaching_plans').select('*').eq('client_id',id).order('created_at',{ascending:false}),appointments:supabase.from('coaching_appointments').select('*').eq('client_id',id).gte('starts_at',new Date().toISOString()).order('starts_at').limit(3),messages:supabase.from('coaching_messages').select('*').eq('client_id',id).order('created_at',{ascending:false}).limit(200),notes:supabase.from('coaching_notes').select('*').eq('client_id',id).order('created_at',{ascending:false})};const entries=await Promise.all(Object.entries(requests).map(async([key,promise])=>{const result=await promise,value=result.data??(key==='profile'?null:[]);return[key,key==='messages'?[...value].reverse():value,result.error]}));if(requestId!==selectionRequest)return;detail=Object.fromEntries(entries.map(([key,value])=>[key,value]));renderDossier();if(entries.some(([, ,error])=>error))notify('Certaines parties du dossier ne peuvent pas être chargées. Réessayez dans un instant.','error');channel=supabase.channel(`coach:${id}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'coaching_messages',filter:`client_id=eq.${id}`},payload=>{if(id!==selected?.client_id)return;if(!(detail.messages||[]).some(row=>row.id===payload.new.id)){detail.messages.push(payload.new);const list=$('#coach-message-list');if(list)list.innerHTML=messageMarkup();}}).subscribe();await supabase.from('coaching_messages').update({read_at:new Date().toISOString()}).eq('client_id',id).eq('sender_id',id).is('read_at',null);if(id!==selected?.client_id)return;selected.unread_messages=0;renderMetrics();renderClients($('#coach-client-search').value);}

const actionConfig={goal:['Nouvel objectif','coaching_goals'],task:['Nouvelle action','coaching_tasks'],habit:['Nouvelle habitude','coaching_habits'],assignment:['Assigner une leçon','coaching_assignments'],checkin:['Planifier un bilan','coaching_checkins'],appointment:['Planifier un rendez-vous','coaching_appointments'],plan:['Publier un plan','coaching_plans'],review:['Publier un compte rendu','coaching_reviews'],note:['Ajouter une note privée','coaching_notes'],profile:['Modifier les priorités','coaching_profiles']};
function openAction(kind){const form=$('#coach-action-form');form.reset();form.elements.kind.value=kind;$('#coach-action-title').textContent=actionConfig[kind][0];form.querySelector('[data-action-module]').hidden=kind!=='assignment';form.querySelector('[data-action-description]').hidden=false;form.querySelector('[data-action-date]').hidden=!['goal','task','assignment','checkin','appointment','plan','review'].includes(kind);form.querySelector('[data-action-visible]').hidden=!['plan','review'].includes(kind);form.elements.title.closest('label').hidden=['assignment','checkin','profile'].includes(kind);form.elements.title.required=!['assignment','checkin','profile'].includes(kind);form.elements.date.required=['checkin','appointment'].includes(kind);form.elements.description.closest('label').querySelector('span').textContent=kind==='note'?'Note confidentielle':kind==='profile'?'Priorités, une par ligne':kind==='checkin'?'Consigne du bilan':kind==='appointment'?'Note':'Contenu ou consigne';if(kind==='profile')form.elements.description.value=(detail.profile?.priorities||[]).join('\n');$('#coach-action-dialog').showModal();}
async function saveAction(form){const values=Object.fromEntries(new FormData(form)),kind=values.kind,base={client_id:selected.client_id};if(kind==='profile'){const priorities=values.description.split('\n').map(item=>item.trim()).filter(Boolean);const {error}=await supabase.from('coaching_profiles').update({priorities}).eq('client_id',selected.client_id);if(error){form.querySelector('[role=status]').textContent='Les priorités n’ont pas pu être enregistrées.';return;}$('#coach-action-dialog').close();await selectClient(selected.client_id);return;}let table,payload;switch(kind){case'goal':table='coaching_goals';payload={...base,title:values.title,description:values.description,target_date:values.date?values.date.slice(0,10):null,created_by:user.id};break;case'task':table='coaching_tasks';payload={...base,title:values.title,description:values.description,due_at:values.date||null,created_by:user.id};break;case'habit':table='coaching_habits';payload={...base,title:values.title,description:values.description,created_by:user.id};break;case'assignment':table='coaching_assignments';payload={...base,module_id:values.module_id,note:values.description,due_at:values.date||null,assigned_by:user.id};break;case'checkin':{const due=new Date(values.date),day=due.getDay()||7,start=new Date(due);start.setDate(due.getDate()-day+1);const end=new Date(start);end.setDate(start.getDate()+6);table='coaching_checkins';payload={...base,period_start:start.toISOString().slice(0,10),period_end:end.toISOString().slice(0,10),due_at:due.toISOString(),comment:values.description};break;}case'appointment':table='coaching_appointments';payload={...base,starts_at:values.date,note:values.description,created_by:user.id};break;case'plan':table='coaching_plans';payload={...base,title:values.title,content:values.description,status:'active',starts_on:values.date?values.date.slice(0,10):null,visible_to_client:values.visible_to_client==='on',created_by:user.id};break;case'review':table='coaching_reviews';payload={...base,title:values.title,content:values.description,kind:'monthly',period_end:values.date?values.date.slice(0,10):null,visible_to_client:values.visible_to_client==='on',created_by:user.id};break;default:table='coaching_notes';payload={...base,content:values.description||values.title,author_id:user.id};}
  const {error}=await supabase.from(table).insert(payload);if(error){form.querySelector('[role=status]').textContent='Cet élément n’a pas pu être enregistré.';return;}$('#coach-action-dialog').close();await selectClient(selected.client_id);notify('Le parcours a été mis à jour.','success');}

async function removeCoaching(button){if(!isAdmin||!selected)return;if(!confirm(`Retirer immédiatement le Coaching à ${selected.display_name} ?\n\nSon historique sera conservé.`))return;button.disabled=true;const {error}=await supabase.rpc('admin_revoke_coaching_access',{p_client_id:selected.client_id});if(error){button.disabled=false;return notify('Le Coaching n’a pas pu être retiré.','error');}selected.status='cancelled';const client=clients.find(row=>row.client_id===selected.client_id);if(client)client.status='cancelled';renderMetrics();renderClients($('#coach-client-search').value);renderDossier();notify(`Le Coaching de ${selected.display_name} a été retiré.`,'success');}
const localDateKey=value=>{const date=new Date(value);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;};
const sameLocalDay=(left,right)=>localDateKey(left)===localDateKey(right);
const calendarMonthEnd=month=>new Date(month.getFullYear(),month.getMonth()+1,1);
const calendarTimes=()=>Array.from({length:37},(_,index)=>{const minutes=9*60+index*15;return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;});
const slotAt=(day,time)=>availabilitySlots.find(slot=>{const date=new Date(slot.starts_at),slotTime=`${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`;return sameLocalDay(date,day)&&slotTime===time;});
const dateAtTime=(day,time)=>{const [hours,minutes]=time.split(':').map(Number),date=new Date(day);date.setHours(hours,minutes,0,0);return date;};
function setCalendarStatus(message='',tone=''){const node=$('#coach-calendar-status');node.textContent=message;node.dataset.tone=tone;}
function renderAvailabilityCalendar(){
  const monthTitle=new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric'}).format(availabilityMonth);
  $('#coach-calendar-title').textContent=monthTitle[0].toUpperCase()+monthTitle.slice(1);
  const first=new Date(availabilityMonth),offset=(first.getDay()+6)%7,start=new Date(first);start.setDate(first.getDate()-offset);
  $('#coach-calendar-grid').innerHTML=Array.from({length:42},(_,index)=>{const day=new Date(start);day.setDate(start.getDate()+index);const rows=availabilitySlots.filter(slot=>sameLocalDay(slot.starts_at,day)),available=rows.filter(slot=>slot.status==='available').length,booked=rows.filter(slot=>slot.status==='booked').length,outside=day.getMonth()!==availabilityMonth.getMonth(),past=new Date(day).setHours(23,59,59,999)<Date.now();return `<button type="button" data-calendar-day="${localDateKey(day)}" class="${outside?'outside ':''}${sameLocalDay(day,availabilityDay)?'selected ':''}${sameLocalDay(day,new Date())?'today ':''}" ${past?'disabled':''}><span>${day.getDate()}</span>${available||booked?`<small>${available?`${available} libre${available>1?'s':''}`:''}${available&&booked?' · ':''}${booked?`${booked} réservé${booked>1?'s':''}`:''}</small>`:'<small>—</small>'}</button>`;}).join('');
  renderAvailabilityTimes();
}
function renderAvailabilityTimes(){
  const dayLabel=new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long'}).format(availabilityDay);
  $('#coach-calendar-day-title').textContent=dayLabel[0].toUpperCase()+dayLabel.slice(1);
  const cutoff=Date.now()+8*3600000;
  $('#coach-calendar-times').innerHTML=calendarTimes().map(time=>{const slot=slotAt(availabilityDay,time),date=dateAtTime(availabilityDay,time),status=slot?.status||'',disabled=date.getTime()<cutoff||status==='booked';return `<button type="button" data-calendar-time="${time}" class="${status}" ${disabled?'disabled':''}><span>${time.replace(':',' h ')}</span><small>${status==='available'?'Disponible':status==='booked'?'Réservé':date.getTime()<cutoff?'Indisponible':'Ajouter'}</small></button>`;}).join('');
  const daySlots=availabilitySlots.filter(slot=>sameLocalDay(slot.starts_at,availabilityDay)),free=daySlots.filter(slot=>slot.status==='available').length,booked=daySlots.filter(slot=>slot.status==='booked').length;
  $('#coach-calendar-summary').textContent=`${free} créneau${free>1?'x':''} libre${free>1?'s':''}${booked?` · ${booked} réservé${booked>1?'s':''}`:''}`;
  document.querySelector('[data-clear-day]').disabled=!free;
}
async function loadAvailability(){
  setCalendarStatus('Chargement du calendrier…');
  const start=new Date(availabilityMonth.getFullYear(),availabilityMonth.getMonth(),1),end=calendarMonthEnd(availabilityMonth);
  const {data,error}=await supabase.from('coaching_availability_slots').select('*').eq('coach_id',user.id).gte('starts_at',start.toISOString()).lt('starts_at',end.toISOString()).order('starts_at');
  if(error){setCalendarStatus('Le calendrier ne peut pas être chargé.','error');return;}
  availabilitySlots=data||[];setCalendarStatus('');renderAvailabilityCalendar();
}
async function toggleAvailability(time,button){
  const existing=slotAt(availabilityDay,time);button.disabled=true;setCalendarStatus('Mise à jour…');
  const request=existing?.status==='available'?supabase.from('coaching_availability_slots').delete().eq('id',existing.id).eq('status','available'):supabase.from('coaching_availability_slots').insert({coach_id:user.id,starts_at:dateAtTime(availabilityDay,time).toISOString(),duration_minutes:15});
  const {error}=await request;if(error){setCalendarStatus('Ce créneau n’a pas pu être modifié.','error');button.disabled=false;return;}await loadAvailability();
}
async function applyAvailabilityPreset(kind,button){
  const ranges={morning:[9*60,12*60],afternoon:[14*60,18*60],day:[9*60,18*60]},[start,end]=ranges[kind],cutoff=Date.now()+8*3600000;
  const rows=calendarTimes().filter(time=>{const [hours,minutes]=time.split(':').map(Number),total=hours*60+minutes;return total>=start&&total<end&&!slotAt(availabilityDay,time)&&dateAtTime(availabilityDay,time).getTime()>=cutoff;}).map(time=>({coach_id:user.id,starts_at:dateAtTime(availabilityDay,time).toISOString(),duration_minutes:15}));
  if(!rows.length)return setCalendarStatus('Tous ces horaires sont déjà publiés.');button.disabled=true;setCalendarStatus('Publication des créneaux…');const {error}=await supabase.from('coaching_availability_slots').insert(rows);button.disabled=false;if(error)return setCalendarStatus('Les créneaux n’ont pas pu être publiés.','error');await loadAvailability();
}
async function clearAvailabilityDay(button){const ids=availabilitySlots.filter(slot=>sameLocalDay(slot.starts_at,availabilityDay)&&slot.status==='available').map(slot=>slot.id);if(!ids.length)return;button.disabled=true;setCalendarStatus('Suppression…');const {error}=await supabase.from('coaching_availability_slots').delete().in('id',ids);button.disabled=false;if(error)return setCalendarStatus('Les créneaux n’ont pas pu être supprimés.','error');await loadAvailability();}
document.addEventListener('click',async event=>{
  const close=event.target.closest('[data-close-dialog]');if(close)return close.closest('dialog').close();
  const day=event.target.closest('[data-calendar-day]');if(day){const [year,month,date]=day.dataset.calendarDay.split('-').map(Number);availabilityDay=new Date(year,month-1,date);if(availabilityMonth.getFullYear()!==year||availabilityMonth.getMonth()!==month-1){availabilityMonth=new Date(year,month-1,1);return loadAvailability();}renderAvailabilityCalendar();return;}
  const time=event.target.closest('[data-calendar-time]');if(time&&!time.disabled)return toggleAvailability(time.dataset.calendarTime,time);
  const preset=event.target.closest('[data-calendar-preset]');if(preset)return applyAvailabilityPreset(preset.dataset.calendarPreset,preset);
  const clear=event.target.closest('[data-clear-day]');if(clear)return clearAvailabilityDay(clear);
  if(event.target.closest('[data-calendar-prev]')){availabilityMonth=new Date(availabilityMonth.getFullYear(),availabilityMonth.getMonth()-1,1);availabilityDay=new Date(availabilityMonth);return loadAvailability();}
  if(event.target.closest('[data-calendar-next]')){availabilityMonth=new Date(availabilityMonth.getFullYear(),availabilityMonth.getMonth()+1,1);availabilityDay=new Date(availabilityMonth);return loadAvailability();}
  if(event.target.closest('[data-calendar-today]')){availabilityMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);availabilityDay=new Date();return loadAvailability();}
  const remove=event.target.closest('[data-remove-coaching]');if(remove)return removeCoaching(remove);const client=event.target.closest('[data-client]');if(client)return selectClient(client.dataset.client);const add=event.target.closest('[data-new]');if(add){add.closest('details')?.removeAttribute('open');return openAction(add.dataset.new);}const tab=event.target.closest('[data-dossier-tab]');if(tab){document.querySelectorAll('[data-dossier-tab]').forEach(node=>node.classList.toggle('active',node===tab));document.querySelectorAll('[data-tab]').forEach(node=>node.classList.toggle('active',node.dataset.tab===tab.dataset.dossierTab));}
});
document.addEventListener('submit',async event=>{if(event.target.id==='coach-action-form'){event.preventDefault();return saveAction(event.target);}if(event.target.id==='coach-message-form'){event.preventDefault();const field=event.target.elements.content,content=field.value.trim();if(!content)return;const {error}=await supabase.from('coaching_messages').insert({client_id:selected.client_id,sender_id:user.id,content});if(error)return notify('Le message n’a pas pu être envoyé.','error');field.value='';}});
const normalizeUsername=value=>String(value||'').replace(/^@+/,'').trim().toLocaleLowerCase('fr-FR');
document.querySelectorAll('#coach-access-form input[name$="_username"]').forEach(input=>input.addEventListener('input',()=>{input.value=normalizeUsername(input.value);}));
const updateAccessOfferFields=()=>{const coaching=$('#coach-access-form').elements.offer.value==='coaching';document.querySelectorAll('[data-coaching-access-field]').forEach(node=>node.hidden=!coaching);document.querySelectorAll('[data-academy-access-field]').forEach(node=>node.hidden=coaching);};
$('#coach-client-search').addEventListener('input',renderClients);$('#coach-client-filter').addEventListener('change',renderClients);$('#coach-add-client').addEventListener('click',()=>{$('#coach-access-form').reset();updateAccessOfferFields();$('#coach-access-dialog').showModal();});$('#coach-access-form').elements.offer.addEventListener('change',updateAccessOfferFields);$('#coach-access-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form)),status=form.querySelector('[role=status]'),button=form.querySelector('[type=submit]');button.disabled=true;status.textContent='Mise à jour en cours…';const request=values.offer==='coaching'?supabase.rpc('admin_set_coaching_client_by_username',{p_client_username:normalizeUsername(values.client_username),p_coach_username:normalizeUsername(values.coach_username)||null,p_status:values.status,p_access_source:'manual',p_stripe_subscription_id:null}):supabase.rpc('admin_set_academy_access_by_username',{p_username:normalizeUsername(values.client_username),p_active:values.academy_action==='grant',p_ends_at:values.academy_ends_at||null,p_note:values.academy_note||null});const {error}=await request;button.disabled=false;status.textContent=error?'La mise à jour de l’accès a échoué.':values.offer==='coaching'?'Accès Coaching activé.':values.academy_action==='grant'?'Accès Académie accordé gratuitement.':'Accès Académie manuel retiré.';if(!error&&values.offer==='coaching')setTimeout(()=>location.reload(),500);});
$('#coach-availability').addEventListener('click',()=>{availabilityDay=new Date(Date.now()+24*3600000);availabilityMonth=new Date(availabilityDay.getFullYear(),availabilityDay.getMonth(),1);$('#coach-availability-dialog').showModal();loadAvailability();});

async function initialize(){user=(await supabase.auth.getSession()).data.session?.user;if(!user){location.replace('/#connexion');return;}const [{data:staff},{data:profile},{data:rows,error},{data:moduleRows}]=await Promise.all([supabase.rpc('is_coaching_staff'),supabase.from('profiles').select('role,username').eq('id',user.id).single(),supabase.rpc('get_coaching_client_summaries'),supabase.from('modules').select('id,title,order_index,chapters(title,order_index)').order('order_index')]);if(!staff||error){location.replace('/accueil');return;}isAdmin=profile?.role==='admin';$('#coach-add-client').hidden=!isAdmin;if(profile?.username)$('#coach-access-form').elements.coach_username.placeholder=`Votre compte : ${profile.username}`;clients=rows||[];modules=moduleRows||[];$('#coach-action-form').elements.module_id.innerHTML=modules.map(row=>`<option value="${row.id}">${esc(row.chapters?.title||'Académie')} — ${esc(row.title)}</option>`).join('');renderMetrics();renderClients();if(clients[0])selectClient(clients[0].client_id);}
addEventListener('pagehide',()=>{if(channel)supabase.removeChannel(channel);});initialize();
